using T = int;
T val = 1;
const T c_val = 2;

T* p_non_const = &val;
const T* p_const = &c_val;

// Conditional operator (?:) requires a Composite Pointer Type.
// Composite(T*, const T*) must be the common qualified type: const T*
auto p_comp = true ? p_non_const : p_const; // p_comp is const T*

// Failure example: Cannot assign Composite (const T*) back to T*
// T* p_err = p_comp; // Error: incompatible cv-qualifiers
                      // (Discards 'const')
